class Circle:
    def __init__(self, radius):
        self.radius = radius

    @property
    def area(self):
        return round(3.14159 * self.radius ** 2, 2)

    @classmethod
    def from_diameter(cls, d):
        return cls(d / 2)

    @staticmethod
    def unit():
        return "cm"

c = Circle.from_diameter(10)
print(c.radius, c.area, Circle.unit())

