questions.solution:
class Product:
    def __init__(self, name, price):
        self.name = name
        self.price = price

    @property
    def price(self):
        return self._price

    @price.setter
    def price(self, value):
        if value < 0:
            raise ValueError("price cannot be negative")
        self._price = value

tests.code:
try:
    Product('mug', 8).__setattr__('price', -1)
except ValueError:
    pass
else:
    raise AssertionError('Setting a negative price should raise ValueError.')

try:
    Product('mug', -3)
except ValueError:
    pass
else:
    raise AssertionError('Creating a product with a negative price should raise ValueError too.')

