questions.solution:
class Invoice:
    def __init__(self, customer):
        self.customer = customer
        self.lines = []

    @classmethod
    def empty(cls, customer):
        return cls(customer)

    def add_line(self, description, amount):
        self.lines.append((description, amount))

    @property
    def subtotal(self):
        return round(sum(a for d, a in self.lines), 2)

    @property
    def tax(self):
        return round(self.subtotal * 0.2, 2)

    @property
    def total(self):
        return round(self.subtotal + self.tax, 2)
